import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate the successful registration of a new Todo List user.
 *
 * This test covers the end-to-end registration process for a standard user via
 * POST /auth/user/join:
 *
 * 1. Generates a unique, valid email address for the user.
 * 2. Creates a strong password (minimum 8 characters, letters and numbers).
 * 3. Generates a display name within 2-50 UTF-8 characters.
 * 4. Provides required audit fields: href (window.location.href) and referrer
 *    (document.referrer) as URI strings.
 * 5. Calls the registration API (api.functional.auth.user.join) with these
 *    details.
 * 6. Asserts that the response includes a valid user profile with required fields:
 *    id (uuid), email, display_name, timestamps (created_at/updated_at), and
 *    deleted_at is null or undefined.
 * 7. Validates the returned token structure (access/refresh tokens and expiration
 *    fields) complies with IAuthorizationToken.
 * 8. Ensures the account is created and is pending email confirmation (deleted_at
 *    is null), per business requirement.
 * 9. Verifies that provided href and referrer are accepted.
 */
export async function test_api_user_registration_success(
  connection: api.IConnection,
) {
  // Generate unique and valid registration input strictly following DTO constraints
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(10) + "A"; // Ensure at least 8 chars, includes letters/numbers
  const displayName = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 2,
    wordMax: 8,
  });
  const href = "https://frontend.todo.test/signup";
  const referrer = "https://frontend.todo.test/";
  const body = {
    email,
    password,
    display_name: displayName,
    href,
    referrer,
  } satisfies ITodoListUser.IJoin;

  // Register user via API
  const result = await api.functional.auth.user.join(connection, {
    body,
  });
  typia.assert<ITodoListUser.IAuthorized>(result);

  // Validate returned fields and token structure
  TestValidator.predicate(
    "user id must be valid uuid",
    typeof result.id === "string" && result.id.length > 0,
  );
  TestValidator.equals("returned email matches input", result.email, email);
  TestValidator.equals(
    "returned display_name matches input",
    result.display_name,
    displayName,
  );
  TestValidator.predicate(
    "created_at is date-time",
    typeof result.created_at === "string" && result.created_at.includes("T"),
  );
  TestValidator.predicate(
    "updated_at is date-time",
    typeof result.updated_at === "string" && result.updated_at.includes("T"),
  );
  TestValidator.equals(
    "deleted_at is null or undefined after registration",
    result.deleted_at,
    null,
  );
  typia.assert<IAuthorizationToken>(result.token);
  TestValidator.predicate(
    "token.access and token.refresh are non-empty",
    result.token.access.length > 0 && result.token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate registration endpoint enforces unique email constraint.
 *
 * This test ensures that a user's email address cannot be registered more than
 * once. It:
 *
 * 1. Registers a new user using a random, valid email address.
 * 2. Attempts to register a second user with the exact same email but different
 *    password, display_name, href, and referrer.
 * 3. Asserts that the second registration fails with an appropriate duplicate
 *    email error.
 * 4. (If possible) Ensures that only one account exists for the target email,
 *    trusting backend enforcement for unique constraint.
 *
 * Steps:
 *
 * - Step 1: Register user with random valid email and details (using
 *   ITodoListUser.IJoin)
 * - Step 2: Re-attempt registration with same email and new valid details
 *   (ITodoListUser.IJoin)
 * - Step 3: Assert that second registration is rejected
 * - Step 4: (If supported by API) Confirm only one registration exists for email
 *   (otherwise skip)
 *
 * This guarantees that registration endpoint prohibits duplicate email and no
 * new users are created in that case.
 */
export async function test_api_user_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Generate a unique valid email for the test
  const email = typia.random<string & tags.Format<"email">>();

  // Step 1: Register the initial user
  const initialJoin = {
    email,
    password: RandomGenerator.alphaNumeric(12) + "aA1", // ensure mix
    display_name: RandomGenerator.name(2),
    href: "https://" + RandomGenerator.alphaNumeric(8) + ".test/join",
    referrer: "https://" + RandomGenerator.alphaNumeric(6) + ".test/home",
  } satisfies ITodoListUser.IJoin;
  const initialResult = await api.functional.auth.user.join(connection, {
    body: initialJoin,
  });
  typia.assert(initialResult);
  TestValidator.equals(
    "registered email matches input",
    initialResult.email,
    email,
  );
  TestValidator.equals(
    "registered display_name matches input",
    initialResult.display_name,
    initialJoin.display_name,
  );

  // Step 2: Attempt duplicate registration with same email but different details
  const duplicateJoin = {
    email, // duplicate
    password: RandomGenerator.alphaNumeric(16) + "bB2", // different password
    display_name: RandomGenerator.name(3), // different display name
    href: "https://" + RandomGenerator.alphaNumeric(10) + ".test/dupreg",
    referrer: "https://" + RandomGenerator.alphaNumeric(5) + ".test/some",
  } satisfies ITodoListUser.IJoin;

  // Step 3: Assert duplicate registration fails
  await TestValidator.error(
    "duplicate email registration should be rejected",
    async () => {
      await api.functional.auth.user.join(connection, { body: duplicateJoin });
    },
  );

  // Step 4: (If enumeration possible, otherwise skip)
  // No API for listing users by email, so no further direct validation possible
}

