import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

/**
 * Validate that a user can retrieve their own authentication session list, test
 * filtering, pagination, status, date, and text search, and verify isolation by
 * actor.
 */
export async function test_api_user_session_list_self_access(
  connection: api.IConnection,
) {
  // 1. Register user1 and obtain authentication context
  const user1JoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
    href: "https://app.todolist.local/register",
    referrer: "https://app.todolist.local/welcome",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies ITodoListUser.IJoin;
  const user1Auth = await api.functional.auth.user.join(connection, {
    body: user1JoinBody,
  });
  typia.assert(user1Auth);
  const user1Id = user1Auth.id;

  // 2. Register user2 for cross-user access test
  const user2JoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
    href: "https://app.todolist.local/register",
    referrer: "https://app.todolist.local/welcome",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies ITodoListUser.IJoin;
  const user2Auth = await api.functional.auth.user.join(connection, {
    body: user2JoinBody,
  });
  typia.assert(user2Auth);
  const user2Id = user2Auth.id;

  // 3. Retrieve user1 session list with default pagination
  const basePageReq = {
    page: 1,
    limit: 10,
  } satisfies ITodoListUserSession.IRequest;
  const user1Sessions = await api.functional.todoList.user.users.sessions.index(
    connection,
    {
      userId: user1Id,
      body: basePageReq,
    },
  );
  typia.assert(user1Sessions);
  TestValidator.equals(
    "user1 returned sessions belong to user1",
    user1Sessions.data.every((s) => s.todo_list_user_id === user1Id),
    true,
  );

  // 4. Filtering by status: show active and expired sessions (all possible values)
  const allStatuses = [undefined, "active", "expired"] as const;
  for (const status of allStatuses) {
    const req = {
      ...basePageReq,
      status,
    } satisfies ITodoListUserSession.IRequest;
    const filtered = await api.functional.todoList.user.users.sessions.index(
      connection,
      {
        userId: user1Id,
        body: req,
      },
    );
    typia.assert(filtered);
    TestValidator.equals(
      "filtered user1 sessions belong to user1",
      filtered.data.every((s) => s.todo_list_user_id === user1Id),
      true,
    );
    if (status) {
      const allMatch = filtered.data.every((s) =>
        status === "active"
          ? !s.expired_at
          : s.expired_at !== null && s.expired_at !== undefined,
      );
      TestValidator.equals(
        `all user1 session status are ${status}`,
        allMatch,
        true,
      );
    }
  }

  // 5. Filtering by creation date
  const nowIso = new Date().toISOString();
  const dateReq = {
    ...basePageReq,
    from: nowIso,
    to: nowIso,
  } satisfies ITodoListUserSession.IRequest;
  const dateFiltered = await api.functional.todoList.user.users.sessions.index(
    connection,
    {
      userId: user1Id,
      body: dateReq,
    },
  );
  typia.assert(dateFiltered);
  TestValidator.equals(
    "user1 session date filter matches",
    dateFiltered.data.every((s) => s.todo_list_user_id === user1Id),
    true,
  );

  // 6. Filtering by text search
  if (user1Sessions.data.length > 0) {
    const searchIp = user1Sessions.data[0].ip;
    const searchReq = {
      ...basePageReq,
      search: searchIp,
    } satisfies ITodoListUserSession.IRequest;
    const searchResult =
      await api.functional.todoList.user.users.sessions.index(connection, {
        userId: user1Id,
        body: searchReq,
      });
    typia.assert(searchResult);
    TestValidator.equals(
      "user1 session text search matches",
      searchResult.data.every((s) => s.todo_list_user_id === user1Id),
      true,
    );
    if (searchResult.data.length > 0) {
      TestValidator.equals(
        "text search result contains ip",
        searchResult.data.some((s) => s.ip === searchIp),
        true,
      );
    }
  }

  // 7. Pagination: request a different page size (smaller limit)
  const pagedReq = {
    ...basePageReq,
    page: 1,
    limit: 1,
  } satisfies ITodoListUserSession.IRequest;
  const pagedResult = await api.functional.todoList.user.users.sessions.index(
    connection,
    {
      userId: user1Id,
      body: pagedReq,
    },
  );
  typia.assert(pagedResult);
  TestValidator.equals(
    "pagination works for user1",
    pagedResult.pagination.limit,
    1,
  );

  // 8. Attempt user2 to access user1's sessions, should fail
  await api.functional.auth.user.join(connection, { body: user2JoinBody }); // Issue token for user2
  await TestValidator.error(
    "user2 cannot access user1's sessions",
    async () => {
      await api.functional.todoList.user.users.sessions.index(connection, {
        userId: user1Id,
        body: basePageReq,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdminSession";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

/**
 * Validate the administrator's ability to review user session history.
 *
 * 1. Register new admin (obtain admin session credentials)
 * 2. Register new user (and trigger a session by joining)
 * 3. As admin, fetch the user's session list and verify all session data matches
 *    expected userId
 * 4. Use pagination (page=1, limit=1) to test pagination logic
 * 5. Use search/filtering (search/referrer/ip/from/to/status) to test all advanced
 *    parameters
 * 6. Attempt to use session-list as a regular user, confirm access is denied
 *
 * Also asserts that essential session metadata (ip, href, referrer, created_at,
 * expired_at) exist and are correct types.
 */
export async function test_api_admin_session_list_user_review(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminReq = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    href: "https://test-admin-join.com/" + RandomGenerator.alphaNumeric(8),
    referrer: "https://referrer.com/" + RandomGenerator.alphaNumeric(6),
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies ITodoListAdmin.ICreate;
  const admin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminReq });
  typia.assert(admin);

  // 2. Register user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userReq = {
    email: userEmail,
    password: RandomGenerator.alphaNumeric(10) + "1aA",
    display_name: RandomGenerator.name(),
    href: "https://user-join.com/" + RandomGenerator.alphaNumeric(7),
    referrer: "https://user-ref.com/" + RandomGenerator.alphaNumeric(4),
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies ITodoListUser.IJoin;
  const user: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userReq },
  );
  typia.assert(user);

  // 3. As admin, review user's session list (basic)
  const page1: IPageITodoListUserSession =
    await api.functional.todoList.admin.users.sessions.index(connection, {
      userId: user.id,
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 10 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
      },
    });
  typia.assert(page1);
  TestValidator.predicate(
    "sessions belong to correct user",
    page1.data.every((s) => s.todo_list_user_id === user.id),
  );
  TestValidator.predicate("session list not empty", page1.data.length > 0);
  for (const session of page1.data) {
    typia.assert(session);
    TestValidator.equals(
      "session.todo_list_user_id matches user",
      session.todo_list_user_id,
      user.id,
    );
  }

  // 4. Pagination logic: page=1, limit=1
  const paged = await api.functional.todoList.admin.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 1 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
      },
    },
  );
  typia.assert(paged);
  TestValidator.equals("pagination.limit is 1", paged.pagination.limit, 1);
  TestValidator.equals("pagination.current is 1", paged.pagination.current, 1);
  TestValidator.predicate("at most 1 session", paged.data.length <= 1);

  // 5. Use search/filtering
  // Filtering by from/to is tested by using dates from session records
  if (page1.data.length > 0) {
    const targetSession = page1.data[0];
    const fromDate: string & tags.Format<"date-time"> =
      targetSession.created_at;
    const toDate: string & tags.Format<"date-time"> = targetSession.created_at;
    const filter = await api.functional.todoList.admin.users.sessions.index(
      connection,
      {
        userId: user.id,
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 5 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
          search: targetSession.ip,
          from: fromDate,
          to: toDate,
          status: targetSession.expired_at == null ? "active" : "expired",
        },
      },
    );
    typia.assert(filter);
    TestValidator.predicate(
      "filtered results have correct ip and status",
      filter.data.every(
        (s) =>
          s.ip === targetSession.ip &&
          (targetSession.expired_at == null
            ? s.expired_at === null
            : s.expired_at !== null),
      ),
    );
  }

  // 6. Attempt to use session-list as a regular user (should fail)
  // Switch auth context: join as new user (tokens are updated automatically)
  await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10) + "Xz9",
      display_name: RandomGenerator.name(),
      href: "https://other-user-join.com/" + RandomGenerator.alphaNumeric(6),
      referrer: "https://other-user-ref.com/" + RandomGenerator.alphaNumeric(6),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoListUser.IJoin,
  });
  await TestValidator.error(
    "non-admin cannot access other user's session list",
    async () => {
      await api.functional.todoList.admin.users.sessions.index(connection, {
        userId: user.id,
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 1 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdminSession";
import type { ITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSystemSetting";

/**
 * Validate that an admin can update a system setting and that all compliance
 * and business rules are enforced.
 *
 * 1. Register a new admin (to gain token for privileged settings operations)
 * 2. Create a unique setting key and an initial value+description, then perform an
 *    update with them
 * 3. Update again with a new value and a new description
 * 4. Remove the description by updating with description: null (should set
 *    description to null or undefined)
 * 5. For all updates, assert response is valid, version increments by 1,
 *    "updated_at" timestamp advances, and new data is persisted
 * 6. Validate that "value" is within 1-2048 chars, "description" is either 1-1000
 *    chars or null/undefined
 * 7. Test error: value outside allowed limits (too short/long); description too
 *    long; description as empty string (not allowed)
 * 8. For error cases, confirm that update fails and returns error.
 */
export async function test_api_system_settings_update_by_admin(
  connection: api.IConnection,
) {
  // Register and authenticate admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        display_name: RandomGenerator.name(2),
        href: "https://admin.test/registration",
        referrer: "https://admin.test/landing",
        ip: undefined,
      } satisfies ITodoListAdmin.ICreate,
    });
  typia.assert(admin);

  // Prepare system setting key and value for test
  const settingKey = `feature_${RandomGenerator.alphaNumeric(8)}`;
  let version: number | undefined = undefined;
  let updatedAt: string | undefined = undefined;

  // Initial update (required value, with description)
  const initialValue = RandomGenerator.paragraph({ sentences: 10 });
  const initialDescription = RandomGenerator.paragraph({ sentences: 5 });
  let setting = await api.functional.todoList.admin.systemSettings.update(
    connection,
    {
      key: settingKey,
      body: {
        value: initialValue,
        description: initialDescription,
      } satisfies ITodoListSystemSetting.IUpdate,
    },
  );
  typia.assert(setting);
  TestValidator.equals("setting key is correct", setting.key, settingKey);
  TestValidator.equals("setting value persisted", setting.value, initialValue);
  TestValidator.equals(
    "setting description persisted",
    setting.description,
    initialDescription,
  );
  version = setting.version;
  updatedAt = setting.updated_at;

  // Second update (change value & description)
  const updatedValue = RandomGenerator.paragraph({ sentences: 30 });
  const updatedDescription = RandomGenerator.paragraph({ sentences: 8 });
  const setting2 = await api.functional.todoList.admin.systemSettings.update(
    connection,
    {
      key: settingKey,
      body: {
        value: updatedValue,
        description: updatedDescription,
      } satisfies ITodoListSystemSetting.IUpdate,
    },
  );
  typia.assert(setting2);
  TestValidator.equals(
    "version incremented on update",
    setting2.version,
    version + 1,
  );
  TestValidator.notEquals(
    "updated_at timestamp advanced",
    setting2.updated_at,
    updatedAt,
  );
  TestValidator.equals("value updated", setting2.value, updatedValue);
  TestValidator.equals(
    "description updated",
    setting2.description,
    updatedDescription,
  );
  version = setting2.version;
  updatedAt = setting2.updated_at;
  TestValidator.predicate(
    "value within allowed length after update",
    setting2.value.length >= 1 && setting2.value.length <= 2048,
  );
  TestValidator.predicate(
    "description within allowed length after update",
    setting2.description !== null &&
      setting2.description !== undefined &&
      setting2.description.length >= 1 &&
      setting2.description.length <= 1000,
  );

  // Third update: remove description (set to null)
  const valueAfterRemoval = RandomGenerator.paragraph({ sentences: 4 });
  const setting3 = await api.functional.todoList.admin.systemSettings.update(
    connection,
    {
      key: settingKey,
      body: {
        value: valueAfterRemoval,
        description: null,
      } satisfies ITodoListSystemSetting.IUpdate,
    },
  );
  typia.assert(setting3);
  TestValidator.equals(
    "version incremented after removing description",
    setting3.version,
    version + 1,
  );
  TestValidator.equals(
    "description removed (null)",
    setting3.description,
    null,
  );
  TestValidator.equals(
    "value updated after removing description",
    setting3.value,
    valueAfterRemoval,
  );

  // Field constraint: Value too short (empty string)
  await TestValidator.error(
    "value with 0 chars (empty string) should fail",
    async () => {
      await api.functional.todoList.admin.systemSettings.update(connection, {
        key: settingKey,
        body: {
          value: "",
          description: "valid",
        } satisfies ITodoListSystemSetting.IUpdate,
      });
    },
  );

  // Field constraint: Value too long (over 2048 chars)
  await TestValidator.error("value over 2048 chars should fail", async () => {
    await api.functional.todoList.admin.systemSettings.update(connection, {
      key: settingKey,
      body: {
        value: "x".repeat(2049),
        description: "valid",
      } satisfies ITodoListSystemSetting.IUpdate,
    });
  });

  // Field constraint: Description too long (over 1000 chars)
  await TestValidator.error(
    "description over 1000 chars should fail",
    async () => {
      await api.functional.todoList.admin.systemSettings.update(connection, {
        key: settingKey,
        body: {
          value: "normal value",
          description: "y".repeat(1001),
        } satisfies ITodoListSystemSetting.IUpdate,
      });
    },
  );

  // Field constraint: Description as empty string (should fail)
  await TestValidator.error(
    "description as empty string should fail",
    async () => {
      await api.functional.todoList.admin.systemSettings.update(connection, {
        key: settingKey,
        body: {
          value: "another normal value",
          description: "",
        } satisfies ITodoListSystemSetting.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
