import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate todo list search for authenticated user with various filter and
 * pagination criteria.
 *
 * This test does the following:
 *
 * 1. Registers a unique test user and authenticates with the system.
 * 2. (Assumes pre-existing server-side todo data — since no create-todo endpoint
 *    exposed).
 * 3. Performs todo queries with a variety of ITodoListTodo.IRequest options:
 *
 * - Default query (no filters)
 * - Status filter (pending & completed)
 * - Sort by title ascending/descending
 * - Pagination with explicit page/page_size
 * - Full-text search against title/description
 * - Created_at date range filter
 * - Combined filters: e.g. pending in a date range, sorted by created_at
 *
 * 4. Verifies that:
 *
 * - Results all belong to the logged-in user.
 * - Returned todos always match filter/sort/page criteria.
 * - Pagination data is correct.
 * - Unauthenticated users are denied access.
 */
export async function test_api_todo_list_search_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as test user
  const testUserEmail: string = typia.random<string & tags.Format<"email">>();
  const testUserPassword: string = RandomGenerator.alphaNumeric(12);
  const testUserJoin = {
    email: testUserEmail,
    password: testUserPassword as string &
      tags.MinLength<8> &
      tags.Format<"password">,
    display_name: RandomGenerator.name(2) as string &
      tags.MinLength<2> &
      tags.MaxLength<50>,
    href: "https://test.example.com/signup",
    referrer: "https://test.example.com/",
  } satisfies ITodoListUser.IJoin;
  const auth = await api.functional.auth.user.join(connection, {
    body: testUserJoin,
  });
  typia.assert(auth);

  // 2. Populate todos - cannot create via API (assume some exist after registration)

  // 3. Search with default (no filter) — should succeed (maybe empty)
  const defaultResult = await api.functional.todoList.user.todos.index(
    connection,
    { body: {} satisfies ITodoListTodo.IRequest },
  );
  typia.assert(defaultResult);
  TestValidator.equals(
    "paginated data is array",
    Array.isArray(defaultResult.data),
    true,
  );
  // All todos belong to this user (ownership pred)
  await ArrayUtil.asyncForEach(defaultResult.data, async (todo, idx) => {
    TestValidator.equals(
      `all todos user.id = test user (idx=${idx})`,
      todo.user.id,
      auth.id,
    );
  });
  // 4. Search by status (pending)
  const pendingResult = await api.functional.todoList.user.todos.index(
    connection,
    { body: { status: "pending" } satisfies ITodoListTodo.IRequest },
  );
  typia.assert(pendingResult);
  await ArrayUtil.asyncForEach(pendingResult.data, async (todo, idx) => {
    TestValidator.equals(
      `pending filter returned only pending (idx=${idx})`,
      todo.status,
      "pending",
    );
  });
  // 5. Search by status (completed)
  const completedResult = await api.functional.todoList.user.todos.index(
    connection,
    { body: { status: "completed" } satisfies ITodoListTodo.IRequest },
  );
  typia.assert(completedResult);
  await ArrayUtil.asyncForEach(completedResult.data, async (todo, idx) => {
    TestValidator.equals(
      `completed filter returned only completed (idx=${idx})`,
      todo.status,
      "completed",
    );
  });
  // 6. Pagination test — try tiny page_size
  const pagedResult = await api.functional.todoList.user.todos.index(
    connection,
    { body: { page_size: 2 } satisfies ITodoListTodo.IRequest },
  );
  typia.assert(pagedResult);
  TestValidator.equals(
    "pagedResult.data length matches page_size or less",
    pagedResult.data.length <= 2,
    true,
  );
  // 7. Sorting test (sort by title asc/desc)
  for (const sort_order of ["asc", "desc"] as const) {
    const sortResult = await api.functional.todoList.user.todos.index(
      connection,
      {
        body: { sort_by: "title", sort_order } satisfies ITodoListTodo.IRequest,
      },
    );
    typia.assert(sortResult);
    const data = sortResult.data.slice();
    const sorted = [...data].sort((a, b) =>
      sort_order === "asc"
        ? a.title.localeCompare(b.title)
        : b.title.localeCompare(a.title),
    );
    TestValidator.equals(`sort order (${sort_order}) by title`, data, sorted);
  }
  // 8. Date range filter (created_from/created_to)
  if (defaultResult.data.length > 0) {
    // Pick min/max created_at from some result
    const created_ats = defaultResult.data.map((x) => x.created_at);
    const minDate = created_ats.reduce((a, b) => (a < b ? a : b));
    const maxDate = created_ats.reduce((a, b) => (a > b ? a : b));
    const ranged = await api.functional.todoList.user.todos.index(connection, {
      body: {
        created_from: minDate,
        created_to: maxDate,
      } satisfies ITodoListTodo.IRequest,
    });
    typia.assert(ranged);
    await ArrayUtil.asyncForEach(ranged.data, async (todo, idx) => {
      TestValidator.predicate(
        `created_at >= minDate (idx=${idx})`,
        todo.created_at >= minDate,
      );
      TestValidator.predicate(
        `created_at <= maxDate (idx=${idx})`,
        todo.created_at <= maxDate,
      );
    });
  }
  // 9. Full-text search (using substring of first todo's title if exists)
  if (defaultResult.data.length > 0) {
    const firstTitle = defaultResult.data[0].title;
    const query = RandomGenerator.substring(firstTitle);
    const searchResult = await api.functional.todoList.user.todos.index(
      connection,
      {
        body: { query } satisfies ITodoListTodo.IRequest,
      },
    );
    typia.assert(searchResult);
    await ArrayUtil.asyncForEach(searchResult.data, async (todo, idx) => {
      TestValidator.predicate(
        `full-text search matches title/desc (idx=${idx})`,
        todo.title.includes(query),
      );
    });
  }
  // 10. Ownership is always enforced (never see another user)
  await ArrayUtil.asyncForEach(defaultResult.data, async (todo, idx) => {
    TestValidator.equals(
      `ownership: all search result user.id = auth.id (idx=${idx})`,
      todo.user.id,
      auth.id,
    );
  });
  // 11. Unauthorized user cannot access
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated user cannot search todo list",
    async () => {
      await api.functional.todoList.user.todos.index(unauthConn, {
        body: {} satisfies ITodoListTodo.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate retrieval of a specific todo item's details owned by the
 * authenticated user.
 *
 * This test covers multiple cases:
 *
 * 1. A user can successfully retrieve their own todo by its id, and the returned
 *    object fields (id, title, description, status, timestamps) match database
 *    state.
 * 2. Access to another user's todo by id must be forbidden and results in proper
 *    error handling.
 * 3. If a non-existent todo id is requested, the API must return an error.
 *
 * Steps:
 *
 * 1. Register user1 and authenticate.
 * 2. Create a todo as user1 and fetch it by id, verify all details.
 * 3. Register user2, authenticate, and attempt to fetch user1's todo by id (should
 *    fail).
 * 4. As user1, try to fetch a random non-existent todo id (should fail).
 */
export async function test_api_todo_detail_retrieval_by_owner(
  connection: api.IConnection,
) {
  // 1. Register user1
  const user1Join = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10) + "1A",
    display_name: RandomGenerator.name(),
    href: "https://example.com/signup",
    referrer: "https://referrer.com/login",
  } satisfies ITodoListUser.IJoin;
  const user1: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: user1Join },
  );
  typia.assert(user1);

  // 2. Create a todo as user1
  const todoBody = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 5, wordMax: 12 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 5,
      sentenceMax: 10,
      wordMin: 3,
      wordMax: 10,
    }),
  } satisfies ITodoListTodo.ICreate;
  const todo: ITodoListTodo = await api.functional.todoList.user.todos.create(
    connection,
    { body: todoBody },
  );
  typia.assert(todo);

  // 3. Fetch the todo by id as owner
  const fetched: ITodoListTodo = await api.functional.todoList.user.todos.at(
    connection,
    { todoId: todo.id },
  );
  typia.assert(fetched);
  TestValidator.equals("fetched todo id matches created", fetched.id, todo.id);
  TestValidator.equals("fetched todo title matches", fetched.title, todo.title);
  TestValidator.equals(
    "fetched todo description matches",
    fetched.description,
    todo.description,
  );
  TestValidator.equals(
    "fetched todo status matches",
    fetched.status,
    todo.status,
  );
  TestValidator.equals(
    "fetched created_at present",
    typeof fetched.created_at,
    "string",
  );
  TestValidator.equals(
    "fetched updated_at present",
    typeof fetched.updated_at,
    "string",
  );

  // 4. Register user2
  const user2Join = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "!bC",
    display_name: RandomGenerator.name(),
    href: "https://example.com/signup",
    referrer: "https://referrer.com/login",
  } satisfies ITodoListUser.IJoin;
  // Switch to new user session
  await api.functional.auth.user.join(connection, { body: user2Join });
  // 5. Try to fetch user1's todo by id as user2 (should error)
  await TestValidator.error("user2 cannot access user1's todo", async () => {
    await api.functional.todoList.user.todos.at(connection, {
      todoId: todo.id,
    });
  });

  // 6. Switch back to user1
  await api.functional.auth.user.join(connection, { body: user1Join });
  // 7. Try to fetch a non-existent todo id as user1 (should error)
  const randomTodoId = typia.random<
    string & tags.Format<"uuid">
  >() satisfies string as string;
  await TestValidator.error(
    "user1 cannot access non-existent todo",
    async () => {
      await api.functional.todoList.user.todos.at(connection, {
        todoId: randomTodoId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate new todo creation by an authenticated user.
 *
 * - Register and authenticate as a new user (validate token/session issued).
 * - As that user, successfully create a new todo with unique title (edge
 *   values/success case).
 * - System assigns ownership (todo belongs to session user), sets timestamps,
 *   status is 'pending', completed_at and deleted_at are null/undefined.
 * - Attempt to create another todo with identical title for same user (should
 *   fail: title uniqueness enforced).
 * - Validate error cases: invalid title (too short/long/empty/whitespace),
 *   description too long, unauthenticated attempts.
 */
export async function test_api_todo_creation_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10) + "X1",
    display_name: RandomGenerator.name(2),
    href: "https://example.com/register",
    referrer: "https://example.com/landing",
  } satisfies ITodoListUser.IJoin;
  const auth: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: joinBody,
    },
  );
  typia.assert(auth);

  // 2. Create a valid todo
  const todoTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 2,
    wordMax: 8,
  })
    .trim()
    .substring(0, 100);
  const todoDescription = RandomGenerator.paragraph({
    sentences: 7,
    wordMin: 3,
    wordMax: 10,
  });
  const createBody = {
    title: todoTitle,
    description: todoDescription,
  } satisfies ITodoListTodo.ICreate;
  const todo: ITodoListTodo = await api.functional.todoList.user.todos.create(
    connection,
    {
      body: createBody,
    },
  );
  typia.assert(todo);
  // Ownership attribution (id not provided by client, should not be overridable)
  TestValidator.predicate(
    "todo id is uuid",
    typeof todo.id === "string" && todo.id.length === 36,
  );
  TestValidator.equals(
    "todo title matches input",
    todo.title,
    todoTitle.trim(),
  );
  TestValidator.equals(
    "todo description matches input",
    todo.description,
    todoDescription,
  );
  TestValidator.equals("todo status is pending", todo.status, "pending");
  TestValidator.predicate(
    "todo created_at is ISO date",
    typeof todo.created_at === "string" && !isNaN(Date.parse(todo.created_at)),
  );
  TestValidator.predicate(
    "todo updated_at is ISO date",
    typeof todo.updated_at === "string" && !isNaN(Date.parse(todo.updated_at)),
  );
  TestValidator.equals(
    "todo completed_at is null/undefined",
    todo.completed_at,
    null,
  );
  TestValidator.equals(
    "todo deleted_at is null/undefined",
    todo.deleted_at,
    null,
  );

  // 3. Attempt to create todo with duplicate title for same user (should fail)
  await TestValidator.error("duplicate todo title should fail", async () => {
    await api.functional.todoList.user.todos.create(connection, {
      body: {
        title: todoTitle,
      } satisfies ITodoListTodo.ICreate,
    });
  });

  // 4. Field validation cases
  // (a) Title too short (empty string after trimming)
  await TestValidator.error("empty/whitespace title should fail", async () => {
    await api.functional.todoList.user.todos.create(connection, {
      body: {
        title: "   ",
      } satisfies ITodoListTodo.ICreate,
    });
  });
  // (b) Title too long
  const overlongTitle = ArrayUtil.repeat(101, () => "a").join("");
