export async function getTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string;
}): Promise<ITodoListTodo> {
  const todo = await MyGlobal.prisma.todo_list_todos.findFirst({
    where: {
      id: props.todoId,
      todo_list_user_id: props.user.id,
      deleted_at: null,
    },
  });

  if (!todo) {
    throw new HttpException("Todo item not found or forbidden.", 404);
  }

  return {
    id: todo.id,
    title: todo.title,
    description: todo.description ?? undefined,
    status: typia.assert<"pending" | "completed">(todo.status),
    completed_at: todo.completed_at
      ? toISOStringSafe(todo.completed_at)
      : undefined,
    created_at: toISOStringSafe(todo.created_at),
    updated_at: toISOStringSafe(todo.updated_at),
    deleted_at: todo.deleted_at ? toISOStringSafe(todo.deleted_at) : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdminSession";
import { IPageITodoListAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListAdminSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoListAdminAdminsAdminIdSessions(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
  body: ITodoListAdminSession.IRequest;
}): Promise<IPageITodoListAdminSession.ISummary> {
  // Extract pagination and filtering parameters with defaults
  const page = props.body.page !== undefined ? props.body.page : 1;
  const limit = props.body.limit !== undefined ? props.body.limit : 20;
  const skip = (page - 1) * limit;

  // Supported sort fields: "created_at" or "expired_at"
  const sortBy =
    props.body.sort_by !== undefined ? props.body.sort_by : "created_at";
  const sortOrder =
    props.body.sort_order !== undefined ? props.body.sort_order : "desc";

  // Build filtering conditions
  const where = {
    todo_list_admin_id: props.adminId,
    // Session is never deleted (optional, add if schema has deleted_at: null)
    ...(props.body.created_from && {
      created_at: { gte: props.body.created_from },
    }),
    ...(props.body.created_to && {
      created_at: {
        ...(props.body.created_from && { gte: props.body.created_from }),
        lte: props.body.created_to,
      },
    }),
    ...(props.body.expired_from && {
      expired_at: { gte: props.body.expired_from },
    }),
    ...(props.body.expired_to && {
      expired_at: {
        ...(props.body.expired_from && { gte: props.body.expired_from }),
        lte: props.body.expired_to,
      },
    }),
    ...(props.body.ip_like && {
      ip_address: { contains: props.body.ip_like },
    }),
    ...(props.body.referrer_like && {
      referrer: { contains: props.body.referrer_like },
    }),
  };

  // Handle merging of multiple conditions per field
  // For created_at and expired_at, merge gte/lte if both provided
  const createdAtFilter: Record<string, any> = {};
  if (props.body.created_from) createdAtFilter.gte = props.body.created_from;
  if (props.body.created_to) createdAtFilter.lte = props.body.created_to;
  if (Object.keys(createdAtFilter).length > 0)
    (where as any).created_at = createdAtFilter;

  const expiredAtFilter: Record<string, any> = {};
  if (props.body.expired_from) expiredAtFilter.gte = props.body.expired_from;
  if (props.body.expired_to) expiredAtFilter.lte = props.body.expired_to;
  if (Object.keys(expiredAtFilter).length > 0)
    (where as any).expired_at = expiredAtFilter;

  // Query main records and count in parallel
  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_list_admin_sessions.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [sortBy]: sortOrder },
      include: {
        admin: true,
      },
    }),
    MyGlobal.prisma.todo_list_admin_sessions.count({ where }),
  ]);

  // Build session summaries
  const data = sessions.map((session) => ({
    id: session.id,
    // Include direct admin summary fields (from joined session.admin)
    email: session.admin.email,
    display_name: session.admin.display_name,
    created_at: toISOStringSafe(session.admin.created_at),
    updated_at: toISOStringSafe(session.admin.updated_at),
    // All other session-level fields are present in the session object if needed
    // (But per ISummary, only account summary is required)
  }));

  // Pagination info structure
  const pagination = {
    current: page,
    limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return { data, pagination };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSystemSetting";
import { IPageITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListSystemSetting";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoListAdminSystemSettings(props: {
  admin: AdminPayload;
  body: ITodoListSystemSetting.IRequest;
}): Promise<IPageITodoListSystemSetting.ISummary> {
  const { page, limit, sort, key, value, version, description } = props.body;
  const skip = (page - 1) * limit;

  // Build dynamic where condition:
  const where = {
    ...(key !== undefined &&
      key !== null &&
      key !== "" && {
        key: { contains: key, mode: "insensitive" as Prisma.QueryMode },
      }),
    ...(value !== undefined &&
      value !== null &&
      value !== "" && {
        value: { contains: value, mode: "insensitive" as Prisma.QueryMode },
      }),
    ...(version !== undefined &&
      version !== null && {
        version: version,
      }),
    ...(description !== undefined &&
      description !== null &&
      description !== "" && {
        description: {
          contains: description,
          mode: "insensitive" as Prisma.QueryMode,
        },
      }),
  };

  // Build dynamic sorting order:
  let orderBy: { [field: string]: "asc" | "desc" }[] = [{ created_at: "desc" }];
  if (sort && typeof sort === "string" && sort.length > 0) {
    const rawSorts = sort
      .split(",")
      .map((f) => f.trim())
      .filter((x) => x);
    orderBy = rawSorts
      .map((sortKey) => {
        const direction = sortKey.startsWith("-") ? "desc" : "asc";
        const fieldName = sortKey.replace(/^-/, "");
        // Only allow known sortable fields
        if (
          ["created_at", "updated_at", "key", "version"].includes(fieldName)
        ) {
          return { [fieldName]: direction };
        }
        // If non-allowed field, skip (filter out)
        return undefined;
      })
      .filter(Boolean) as { [field: string]: "asc" | "desc" }[];
    if (!orderBy.length) orderBy = [{ created_at: "desc" }];
  }

  const [records, total] = await Promise.all([
    MyGlobal.prisma.todo_list_system_settings.findMany({
      where: where,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.todo_list_system_settings.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: records.map((row) => ({
      id: row.id,
      key: row.key,
      value: row.value,
      version: row.version,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoListUser.IJoin;
}): Promise<ITodoListUser.IAuthorized> {
  // Ensure unique email
  const exists = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });
  if (exists) {
    throw new HttpException("Email address is already registered.", 409);
  }

  // Secure password hashing
  const password_hash = await PasswordUtil.hash(props.body.password);
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const user_id: string & tags.Format<"uuid"> = v4();

  // Insert user (pending confirmation, not deleted)
  const user = await MyGlobal.prisma.todo_list_users.create({
    data: {
      id: user_id,
      email: props.body.email,
      password_hash: password_hash,
      display_name: props.body.display_name,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Placeholder for triggering confirmation email workflow
  // await ConfirmationWorkflow.send(user.email, user.id);

  // JWT token issuance is required by endpoint contract
  const accessExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session_id: string & tags.Format<"uuid"> = v4(); // One-off session for registration context

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session_id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session_id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: user.id,
    email: user.email,
    display_name: user.display_name,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: null,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSystemSetting";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postTodoListAdminSystemSettings(props: {
  admin: AdminPayload;
  body: ITodoListSystemSetting.ICreate;
}): Promise<ITodoListSystemSetting> {
  // Enforce unique key upfront
  const existing = await MyGlobal.prisma.todo_list_system_settings.findFirst({
    where: { key: props.body.key },
  });
  if (existing) {
    throw new HttpException(
      "A system setting with this key already exists.",
      409,
    );
  }

  const now = toISOStringSafe(new Date());
  let descriptionValue = undefined;
  if (Object.prototype.hasOwnProperty.call(props.body, "description")) {
    // Forward provided value: undefined, null, or string
    descriptionValue = props.body.description ?? undefined;
  }

  try {
    const created = await MyGlobal.prisma.todo_list_system_settings.create({
      data: {
        id: v4(),
        key: props.body.key,
        value: props.body.value,
        description: descriptionValue,
        version: 1,
        created_at: now,
        updated_at: now,
      },
    });
    return {
      id: created.id,
      key: created.key,
      value: created.value,
      description: created.description ?? undefined,
      version: created.version,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
    };
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      error.code === "P2002"
    ) {
      throw new HttpException(
        "A system setting with this key already exists.",
        409,
      );
    }
    throw new HttpException("Failed to create system setting.", 500);
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: { id: props.todoId },
  });

  if (!todo || todo.deleted_at) {
    throw new HttpException("Todo not found", 404);
  }

  if (todo.todo_list_user_id !== props.user.id) {
    throw new HttpException(
      "You do not have permission to update this todo",
      403,
    );
  }

  // Check for unique title if title is changing
  if (props.body.title !== undefined && props.body.title !== todo.title) {
    const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
      where: {
        title: props.body.title,
        deleted_at: null,
        todo_list_user_id: props.user.id,
        NOT: { id: props.todoId },
      },
    });
    if (duplicate) {
      throw new HttpException(
        "Another active todo with this title already exists.",
        409,
      );
    }
  }

  const now = toISOStringSafe(new Date());
  let completed_at: string | null | undefined = todo.completed_at
    ? toISOStringSafe(todo.completed_at)
    : null;

  let status = todo.status;
  if (props.body.status !== undefined) {
    status = props.body.status;
    if (props.body.status === "completed") {
      completed_at = now;
    } else if (props.body.status === "pending") {
      completed_at = null;
    }
  }

  const updateData = {
    ...(props.body.title !== undefined ? { title: props.body.title } : {}),
    ...(props.body.description !== undefined
      ? { description: props.body.description }
      : {}),
    ...(props.body.status !== undefined ? { status: props.body.status } : {}),
    ...(props.body.status !== undefined ? { completed_at: completed_at } : {}),
    updated_at: now,
  };

  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: { id: props.todoId },
    data: updateData,
  });

  return {
    id: updated.id,
    title: updated.title,
    description:
      typeof updated.description === "undefined"
        ? undefined
        : updated.description === null
          ? null
          : updated.description,
    status: typia.assert<"pending" | "completed">(updated.status),
    completed_at:
      typeof updated.completed_at === "undefined"
        ? undefined
        : updated.completed_at === null
          ? null
          : toISOStringSafe(updated.completed_at),
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      typeof updated.deleted_at === "undefined"
        ? undefined
        : updated.deleted_at === null
          ? undefined
          : toISOStringSafe(updated.deleted_at),
  };
}

