export async function putTodoListAdminTodosTodoId(props: {
  admin: AdminPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  // Get todo
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: { id: props.todoId },
  });
  if (!todo || todo.deleted_at !== null) {
    throw new HttpException("Todo not found or already deleted", 404);
  }

  // Check title uniqueness if changing
  if (typeof props.body.title === "string" && props.body.title !== todo.title) {
    const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
      where: {
        todo_list_user_id: todo.todo_list_user_id,
        deleted_at: null,
        title: props.body.title,
        id: { not: todo.id },
      },
    });
    if (duplicate) {
      throw new HttpException(
        "Todo title must be unique for active todos of the user",
        409,
      );
    }
  }

  let completed_at = todo.completed_at;
  let status = todo.status;
  if (typeof props.body.status === "string") {
    status = props.body.status;
    if (todo.status !== status) {
      if (status === "completed") {
        completed_at = new Date();
      } else {
        completed_at = null;
      }
    }
  }

  // Prepare update data
  const updateData: Record<string, unknown> = {
    updated_at: toISOStringSafe(new Date()),
  };
  if (typeof props.body.title === "string") updateData.title = props.body.title;
  if ("description" in props.body)
    updateData.description = props.body.description;
  if (typeof status === "string") updateData.status = status;
  updateData.completed_at =
    completed_at !== null ? toISOStringSafe(completed_at) : null;

  // Update todo and log audit in transaction
  const [updatedTodo] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.todo_list_todos.update({
      where: { id: todo.id },
      data: updateData,
    }),
    MyGlobal.prisma.todo_list_audit_logs.create({
      data: {
        id: v4(),
        admin_id: props.admin.id,
        target_user_id: todo.todo_list_user_id,
        event_type: "todo_updated",
        event_time: toISOStringSafe(new Date()),
        details: `Admin ${props.admin.id} updated todo ${todo.id}. Fields changed: ${Object.keys(props.body).join(", ")}`,
      },
    }),
  ]);

  return {
    id: updatedTodo.id,
    title: updatedTodo.title,
    description:
      typeof updatedTodo.description === "string"
        ? updatedTodo.description
        : (updatedTodo.description ?? null),
    status: typia.assert<"pending" | "completed">(updatedTodo.status),
    completed_at:
      updatedTodo.completed_at !== null &&
      typeof updatedTodo.completed_at !== "undefined"
        ? toISOStringSafe(updatedTodo.completed_at)
        : null,
    created_at: toISOStringSafe(updatedTodo.created_at),
    updated_at: toISOStringSafe(updatedTodo.updated_at),
    deleted_at:
      updatedTodo.deleted_at !== null &&
      typeof updatedTodo.deleted_at !== "undefined"
        ? toISOStringSafe(updatedTodo.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { ITodoListAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdminSession";

export async function postAuthAdminJoin(props: {
  body: ITodoListAdmin.ICreate;
}): Promise<ITodoListAdmin.IAuthorized> {
  const existing = await MyGlobal.prisma.todo_list_admins.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Admin email already exists", 409);
  }

  const password_hash = await PasswordUtil.hash(props.body.password);
  const now = toISOStringSafe(new Date());
  const id = v4();

  const admin = await MyGlobal.prisma.todo_list_admins.create({
    data: {
      id,
      email: props.body.email,
      password_hash,
      display_name: props.body.display_name,
      created_at: now,
      updated_at: now,
    },
  });

  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const sessionData: any = {
    id: v4(),
    todo_list_admin_id: admin.id,
    href: props.body.href,
    referrer: props.body.referrer,
    created_at: now,
    expired_at: toISOStringSafe(accessExpires),
  };
  if (props.body.ip !== undefined && props.body.ip !== null) {
    sessionData.ip = props.body.ip satisfies string as string;
  }

  const session = await MyGlobal.prisma.todo_list_admin_sessions.create({
    data: sessionData,
  });

  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  const sessionSummary: ITodoListAdminSession.ISummary = {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name,
    created_at:
      admin.created_at instanceof Date
        ? toISOStringSafe(admin.created_at)
        : admin.created_at,
    updated_at:
      admin.updated_at instanceof Date
        ? toISOStringSafe(admin.updated_at)
        : admin.updated_at,
  };

  return {
    id: admin.id,
    email: admin.email,
    display_name: admin.display_name,
    created_at:
      admin.created_at instanceof Date
        ? toISOStringSafe(admin.created_at)
        : admin.created_at,
    updated_at:
      admin.updated_at instanceof Date
        ? toISOStringSafe(admin.updated_at)
        : admin.updated_at,
    deleted_at:
      admin.deleted_at !== undefined && admin.deleted_at !== null
        ? admin.deleted_at instanceof Date
          ? toISOStringSafe(admin.deleted_at)
          : admin.deleted_at
        : undefined,
    token,
    session: sessionSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.IRequest;
}): Promise<IPageITodoListTodo.ISummary> {
  const userId = props.user.id;
  const {
    query,
    status,
    created_from,
    created_to,
    completed_from,
    completed_to,
    sort_by = "created_at",
    sort_order = "desc",
    page = 1,
    page_size = 20,
  } = props.body;

  const where: Prisma.todo_list_todosWhereInput = {
    todo_list_user_id: userId,
    deleted_at: null,
    ...(status && { status }),
    ...(created_from && { created_at: { gte: created_from } }),
    ...(created_to && {
      created_at: {
        ...(created_from ? { gte: created_from } : {}),
        lte: created_to,
      },
    }),
    ...(created_from && !created_to && { created_at: { gte: created_from } }),
    ...(completed_from && { completed_at: { gte: completed_from } }),
    ...(completed_to && {
      completed_at: {
        ...(completed_from ? { gte: completed_from } : {}),
        lte: completed_to,
      },
    }),
    ...(completed_from &&
      !completed_to && { completed_at: { gte: completed_from } }),
    ...(query && query.length > 0
      ? {
          OR: [
            {
              title: {
                contains: query,
                mode: "insensitive" as Prisma.QueryMode,
              },
            },
            {
              description: {
                contains: query,
                mode: "insensitive" as Prisma.QueryMode,
              },
            },
          ] as Prisma.todo_list_todosWhereInput[],
        }
      : {}),
  };

  const take = page_size;
  const skip = (page - 1) * take;

  const allowedSortBy = [
    "created_at",
    "updated_at",
    "completed_at",
    "title",
  ] as const;
  const orderByField = allowedSortBy.includes(sort_by) ? sort_by : "created_at";
  const orderByDir = sort_order === "asc" ? "asc" : "desc";

  const [todos, total] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.todo_list_todos.findMany({
      where,
      orderBy: { [orderByField]: orderByDir },
      skip,
      take,
      include: {
        user: true,
      },
    }),
    MyGlobal.prisma.todo_list_todos.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: take,
      records: total,
      pages: Math.ceil(total / take),
    },
    data: todos.map((todo) => ({
      id: todo.id,
      title: todo.title,
      status: typia.assert<"pending" | "completed">(todo.status),
      completed_at: todo.completed_at
        ? toISOStringSafe(todo.completed_at)
        : null,
      created_at: toISOStringSafe(todo.created_at),
      updated_at: toISOStringSafe(todo.updated_at),
      ...(todo.user && {
        user: {
          id: todo.user.id,
          email: todo.user.email,
          display_name: todo.user.display_name,
        },
      }),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
